sys_ux_data_broker_transform.script:
function transform(){
	var resultArray = [];
	var mappedSysArray = []
    var grAssoc = new GlideAggregate('svc_ci_assoc');  // Use GlideAggregate for GROUPBY
    grAssoc.addEncodedQuery('ci_id.discovery_source!=Manual Entry');  // Apply filter
    grAssoc.addAggregate('COUNT', 'ci_id');  // Count occurrences of each CI
    grAssoc.groupBy('ci_id');  // Group by CI ID
    grAssoc.query();

	var counter = 0 
    while (grAssoc.next()) {
		counter +=1
		mappedSysArray.push(grAssoc.getValue('ci_id'));
        resultArray.push({

            ci_id: grAssoc.getValue('ci_id'),  // Get CI ID
            ci_name: grAssoc.ci_id.getDisplayValue(),  // Get CI Name
            count: grAssoc.getAggregate('COUNT', 'ci_id')  // Get count of occurrences
        });
    }

	gs.print(JSON.stringify(resultArray))
	gs.print(resultArray.length +"  "+ counter)
    return {"resultArray" : resultArray , "mappedSysArray" : mappedSysArray };  // Return grouped data
}
